// GENUARY 2023
// JAN. 5 (credit: jenslabs)
// Debug view

var mySize, margin;
let seed = Math.random() * 28742;
let tile_count, mySpeed;
let colors1 = "fef9fb-fafdff-fcfbf4-f9f8f6".split("-").map((a) => "#" + a);
let colors2;
let colors_tone1 = "2450A6-639CBF-F2EFBD-F28705-F2380F".split("-").map((a) => "#" + a);
let colors_tone2 = "381A40-90BF2A-F2CB05-BF751B-F24F13".split("-").map((a) => "#" + a);
let colors_tone3 = "D7D7D9-038C33-ACF216-698C1C-97BF04".split("-").map((a) => "#" + a);
let colors_tone4 = "192E40-326A8C-3B758C-7AACBF-C4EAF2".split("-").map((a) => "#" + a);
let colors_tone5 = "6595BF-55B3D9-027373-5A7302-F2AB6D".split("-").map((a) => "#" + a);
let colors_tone6 = "024059-A0A603-D98E04-A67F5D-D9C9BA".split("-").map((a) => "#" + a);
let colors_tone7 = "51608C-6A8AA6-BFCDD9-BF8756-8C512E".split("-").map((a) => "#" + a);
let colors_tone8 = "635C73-272B40-F2DAAC-D99E6A-D97E6A".split("-").map((a) => "#" + a);

let colorset = [];
let lines;
let filter1;

function color_set() {
	colors2 = random([colors_tone1, colors_tone2, colors_tone3, colors_tone4, colors_tone5, colors_tone6, colors_tone7, colors_tone8]);
	// colors2 = colors_tone8;
	colorset[0] = random(colors2);
	colorset[1] = random(colors2);
	colorset[2] = random(colors1);
	colorset[3] = random(colors2);
	colorset[4] = random(colors2);
	colorset[5] = random(colors2);
}

function setup() {
  // pixelDensity(3.0);
	mySize = max(windowWidth, windowHeight);
	margin = mySize / 100;
	createCanvas(mySize, mySize);
	randomSeed(seed);
	filter1 = new makeFilter();
	tile_count = int(random(80, 40));
	mySpeed = int(random(3, 5));
	mySetup();
	background("#202020");
}

function draw() {
	randomSeed(seed);
	background("#202020");
	for (let l of lines) {
		l.run();
	}
	image(overAllTexture, 0, 0);

}

function easeOut(o) {
	return sq(sq(o));
}

function easeInOut(t) {
	if ((t /= 1 / 2) < 1) return (1 / 2) * t * t * t;
	return (1 / 2) * ((t -= 2) * t * t + 2);
}

function mySetup() {
	randomSeed(seed);
	color_set();
	mySize -= margin * 4;
	addLines();
}

function addLines() {
	randomSeed(seed);
	lines = [];
	let w = mySize / tile_count * 2;
	for (let i = 0; i < tile_count + 1; i++) {
		for (let j = 0; j < tile_count + 1; j++) {
			let x = i * w;
			let y = j * w;
			lines.push(new makeLine(x, y, w));
		}
	}
}

class makeLine {
	constructor(x, y, w) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.col1 = random(colors1);
		this.col2 = random(colorset);
		this.settime();
		this.dir = random() < 0.5 ? -1 : 1;
		this.speed = 2;
		this.ang = (int(random(4)) * TAU) / random([2, 4, 8, 4]);
		this.mv = 0;
		this.strWei = random(1, margin * 2);
		this.tog = 0;
		this.intNum = int(random(3));
		this.move = this.w;
		//this.moveY = 0;
	}

	display() {
		push();
		translate(this.x + this.w / 2, this.y + this.w / 2);
		rotate(this.ang);
		strokeCap(PROJECT);
		noFill();
		if (int(seed) % 3 == 0) {
			stroke(this.col1);
		} else {
			stroke(this.col2);
		}
		strokeWeight(this.strWei/20);
		drawingContext.shadowColor = str(random(colorset)) + "1a";
		drawingContext.shadowOffsetX = random(-this.move, this.move) / 5;
		drawingContext.shadowOffsetY = random(this.move, -this.move) / 5;
		drawingContext.shadowBlur = 0;
		rect(2 * this.w, 0,2 * this.move, 0.5 * this.w);
		rect(0, 2 * this.w, 0.5 * this.w, 2 * this.move);

		noStroke();
		fill(this.col2);
		circle(0, 0, random(0.25, 0.5) * this.move);
		pop();
	}

	settime() {
		this.t = -int(random(map(mySpeed, 1, 5, 100, 10)));
		this.t1 = map(mySpeed, 1, 5, 10, 100);
	}

	update() {
		if (this.t >= 0 && this.t < this.t1) {
			let easePar = norm(this.t, 0, this.t1 - 1);
			this.move =
				lerp(-1, 1, easeInOut(easePar)) * this.w * (this.tog * 2 - 1);
		}
		if (this.t1 < this.t) {
			if (this.tog) this.tog = 0;
			else this.tog = 1;
			this.settime();
		}
		this.t++;
	}

	run() {
		this.update();
		this.display();
	}
}

// === Tab: save & filter ===
function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("0105_DebugView_2022", "png");
	}
}

//filter
function makeFilter() {
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(0, 0, 5, 95);
	overAllTexture = createGraphics(width, height);
	overAllTexture.loadPixels();
	for (var i = 0; i < width; i++) { // noprotect
		for (var j = 0; j < height; j++) {
			// if (int(seed) % 2 == 0) {
			// overAllTexture.set(i, j,
			// 			color(0, 0, random(5, 95), noise(i / 3, j / 3, (i * j) / 150) * random(5, 15) / 10));
			// }else{
				overAllTexture.set(i, j,
						color(0, 0, random(5, 15), noise(i / 3, j / 3, (i * j) / 50) * random(5, 15) / 1));
			// }
		}
	}
	overAllTexture.updatePixels();
}

function drawOverPattern() {
	push();
	translate(width / 2, height / 2);
	//rotate(-PI / 2);

	let s = max(width, height) / 1 * sqrt(3) - 2;
	let n = 6;

	for (let theta = TWO_PI / 6; theta < TWO_PI; theta += TWO_PI / 6) { // noprotect
		divideOP(0, 0, s * cos(theta), s * sin(theta), s * cos(theta + TWO_PI / 6), s * sin(theta + TWO_PI / 6), n);
	}
	pop();
}

function prop(x1, y1, x2, y2, k) {
	let x3 = (1 - k) * x1 + k * x2;
	let y3 = (1 - k) * y1 + k * y2;
	return [x3, y3];
}

function divideOP(x1, y1, x2, y2, x3, y3, n) {
	if (n > 1) {
		let [xA, yA] = prop(x1, y1, x2, y2, 1 / 3);
		let [xB, yB] = prop(x1, y1, x2, y2, 2 / 3);
		let [xC, yC] = prop(x2, y2, x3, y3, 1 / 3);
		let [xD, yD] = prop(x2, y2, x3, y3, 2 / 3);
		let [xE, yE] = prop(x3, y3, x1, y1, 1 / 3);
		let [xF, yF] = prop(x3, y3, x1, y1, 2 / 3);
		let [xG, yG] = prop(xF, yF, xC, yC, 1 / 2);
		divideOP(x1, y1, xA, yA, xF, yF, n - 1);
		divideOP(xA, yA, xB, yB, xG, yG, n - 1);
		divideOP(xB, yB, x2, y2, xC, yC, n - 1);
		divideOP(xG, yG, xF, yF, xA, yA, n - 1);
		divideOP(xC, yC, xG, yG, xB, yB, n - 1);
		divideOP(xF, yF, xG, yG, xE, yE, n - 1);
		divideOP(xG, yG, xC, yC, xD, yD, n - 1);
		divideOP(xD, yD, xE, yE, xG, yG, n - 1);
		divideOP(xE, yE, xD, yD, x3, y3, n - 1);
	} else {
		makeTriangle([x1, y1], [x2, y2], [x3, y3]);
	}
}

function makeTriangle(v1, v2, v3) {
	let points = shuffle([v1, v2, v3]);
	let [x1, y1] = points[0];
	let [x2, y2] = points[1];
	let [x3, y3] = points[2];
	let iStep = 1 / (pow(2, floor(random(4, 2))));
	for (let i = 0; i < 1; i += iStep) { // noprotect
		let [x4, y4] = prop(x1, y1, x2, y2, 1 - i);
		let [x5, y5] = prop(x1, y1, x3, y3, 1 - i);
		triangle(x1, y1, x4, y4, x5, y5);
	}
}

